import type { Level, ResourceKind } from "@/types/content";

/**
 * A title-and-route index of every registered resource — no bodies.
 *
 * `src/content/registry.ts` is the source of truth, but importing it drags in
 * every content module behind it: the full markdown of 8 SOPs, 6 workflows,
 * 12 case studies, 8 cheat sheets and the rest. That is exactly what the
 * search page wants and exactly what nothing else does. Progress tracking
 * only ever needs to turn an id or an href into a title, a kind and a
 * duration, and it runs in the browser on nearly every page — so it reads
 * this instead, and the library stays out of those bundles.
 *
 * Generated from the registry and checked against it on every build by
 * `assertResourceIndex()` in `src/lib/related.ts`: a renamed resource, a
 * changed route or a new one that never made it into this file all fail
 * `npm run build`.
 */

export interface ResourceIndexEntry {
  id: string;
  kind: ResourceKind;
  title: string;
  /** 1-2 plain-text sentences. Learning paths use it as the step blurb. */
  summary: string;
  href: string;
  minutes?: number;
  level?: Level;
  tags: string[];
}

