/** Lookup maps, built once at module load. */
const BY_ID = new Map(RESOURCE_INDEX.map((entry) => [entry.id, entry]));
const BY_HREF = new Map(RESOURCE_INDEX.map((entry) => [entry.href, entry]));

/** Resolve a resource by its stable id. */
export function indexById(id: string): ResourceIndexEntry | undefined {
  return BY_ID.get(id);
}

/** Resolve a route to its resource, ignoring a trailing slash. */
export function indexByHref(href: string): ResourceIndexEntry | undefined {
  const normalised = href.length > 1 ? href.replace(/\/+$/, "") : href;
  return BY_HREF.get(normalised);
}

/** Every indexed resource of one kind, in registration order. */
export function indexByKind(kind: ResourceKind): ResourceIndexEntry[] {
  return RESOURCE_INDEX.filter((entry) => entry.kind === kind);
}
